package com.smartbus.auth.repository; import com.smartbus.auth.entity.*; import java.util.*; import org.springframework.data.jpa.repository.*; public interface LoginQrTokenRepository extends JpaRepository<LoginQrToken,UUID>{ Optional<LoginQrToken> findByToken(UUID token); @Modifying @Query("update LoginQrToken q set q.used=true where q.student.id=:studentId and q.used=false") void invalidateUnused(UUID studentId); }
